def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_def = my_def = recent5 = recent10 = recent20 = forgive = punish = 0
    for i in range(n):
        m, o = history[i]
        if m == 'D':
            my_def += 1
        if o == 'D':
            opp_def += 1
            if i >= n - 5:
                recent5 += 1
            if i >= n - 10:
                recent10 += 1
            if i >= n - 20:
                recent20 += 1
        if i > 0 and history[i - 1][0] == 'D':
            if o == 'C':
                forgive += 1
            else:
                punish += 1

    rate = opp_def / float(n)

    if recent20 >= 15:
        return 'D'
    if rate > 0.45:
        return 'D'
    if rate > 0.30:
        if rng.random() < 0.75:
            return 'D'
        return 'C'

    if n >= 2 and history[-2][0] == 'D':
        resp = history[-1][1]
        if resp == 'D':
            if rate <= 0.12 and recent5 <= 2:
                return 'C'
            if rate <= 0.18 and recent10 <= 3 and rng.random() < 0.2:
                return 'C'
            return 'D'
        else:
            if rate <= 0.22 and recent10 <= 4:
                if punish == 0:
                    return 'D'
                if forgive > 3 * punish:
                    return 'D'
            if rate <= 0.12 and n >= 80 and punish == 0:
                return 'D'

    if opp_last == 'D':
        if recent5 >= 3 or recent10 >= 6 or rate > 0.25:
            return 'D'
        if rate <= 0.12 and recent5 <= 1:
            return 'C'
        if n >= 90 and rate <= 0.2 and recent10 <= 3:
            return 'D'
        if recent5 >= 2:
            if rng.random() < 0.55:
                return 'D'
            return 'C'
        if rng.random() < 0.85:
            return 'C'
        return 'D'

    if opp_def == 0 and opp_last == 'C':
        if my_def == 0 and n >= 50:
            return 'D'
        if forgive >= 3:
            return 'D'
        if my_last == 'C' and forgive >= 1:
            return 'D'
        if my_last == 'D':
            return 'C'

    if rate <= 0.08 and recent10 <= 1 and punish == 0 and opp_last == 'C':
        if my_def == 0 and n >= 70:
            return 'D'
        if forgive >= 3:
            return 'D'
        if my_last == 'C' and forgive >= 1:
            return 'D'
        if my_last == 'D':
            return 'C'

    if n >= 90 and rate <= 0.12 and recent10 <= 2 and punish == 0 and forgive >= 1 and opp_last == 'C':
        return 'D'

    if n > 80:
        if rate < 0.15:
            return 'C'
        return 'D'

    return 'C'
